CREATE FUNCTION cache_replace_sum_state(integer, integer)
RETURNS integer
LANGUAGE SQL IMMUTABLE STRICT
AS 'SELECT $1 + $2';
CREATE AGGREGATE cache_replace_sum(integer) (
    SFUNC = cache_replace_sum_state,
    STYPE = integer,
    INITCOND = '0'
);

