DO $$
BEGIN
    FOR relation_index IN 1..258 LOOP
        EXECUTE format(
            'CREATE TABLE cache_pressure_%s('
            'id integer PRIMARY KEY)',
            relation_index);
    END LOOP;
END
$$;
CREATE FUNCTION cache_pressure_fill() RETURNS void
LANGUAGE plpgsql VOLATILE AS $$
BEGIN
    FOR relation_index IN 1..258 LOOP
        EXECUTE format(
            'INSERT INTO cache_pressure_%s VALUES (1)',
            relation_index);
    END LOOP;
END
$$;
